// T-slot nut for aluminium extrusion
// Print orientation: flange down on the build plate, neck pointing up (+Z)

// ---------------- Parameters (mm) ----------------
nut_length      = 10;    // length along X
flange_width    = 12;    // flange width along Y
flange_height   = 3;     // flange thickness, z = 0 .. 3
neck_width      = 7;     // neck width along Y (centred)
total_height    = 7;     // top of neck, z = 7
hole_diameter   = 4.5;   // vertical screw hole through centre
overcut         = 0.5;   // extra length on cutting shapes past faces
$fn             = 64;    // curve resolution

neck_height = total_height - flange_height; // neck height, z = 3 .. 7

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_height]);

        // Centred neck (overlaps the flange slightly so the union is one solid)
        translate([-nut_length/2, -neck_width/2, flange_height - 0.01])
            cube([nut_length, neck_width, neck_height + 0.01]);
    }

    // Vertical screw hole through the full height
    translate([0, 0, -overcut])
        cylinder(d = hole_diameter, h = total_height + 2*overcut, $fn = 64);
}
