```openscad
// Dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, ticks on top face

$fn = 128;

// --- Ring dimensions ---
outer_d   = 50;    // outer diameter
inner_d   = 26;    // inner (bore) diameter
ring_h    = 4;     // ring thickness

// --- Tick mark dimensions ---
tick_count = 12;   // number of evenly spaced ticks
tick_w     = 1;    // groove width
tick_depth = 1.5;  // groove depth from top face
tick_len   = 3;    // radial length inward from outer edge

// --- Clearance for clean boolean cuts ---
eps = 0.5;         // overshoot past cut faces

outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = ring_h, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = ring_h + 2 * eps, r = inner_r);
    }

    // Radial tick grooves, first on +X axis
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, i * 360 / tick_count])
            translate([outer_r - tick_len,
                       -tick_w / 2,
                       ring_h - tick_depth])
                cube([tick_len + eps, tick_w, tick_depth + eps]);
    }
}
```

