```openscad
// Anti-vibration foot for benchtop instrument
// Print orientation: bottom face (with pad recess) on the bed at z = 0

$fn = 128;

// --- Dimensions (mm) ---
base_d      = 50;    // frustum diameter at bottom (z = 0)
top_d       = 40;    // frustum diameter at flat top
height      = 15;    // overall height of foot
recess_d    = 42;    // rubber pad recess diameter (bottom face)
recess_h    = 3;     // rubber pad recess depth
screw_d     = 4.5;   // through hole diameter for screw
eps         = 0.5;   // overcut for clean boolean differences

difference() {
    // Main frustum body
    cylinder(h = height, d1 = base_d, d2 = top_d);

    // Rubber pad recess in bottom face
    translate([0, 0, -eps])
        cylinder(h = recess_h + eps, d = recess_d);

    // Central screw through hole
    translate([0, 0, -eps])
        cylinder(h = height + 2 * eps, d = screw_d);
}
