```openscad
// Stiffened cover panel: flat plate with 3 ribs running along Y

// ---- Plate ----
plate_len   = 80;   // plate length along X (mm)
plate_wid   = 80;   // plate width along Y (mm)
plate_t     = 2;    // plate thickness (mm), z = 0..2

// ---- Ribs ----
rib_count   = 3;    // number of ribs
rib_t       = 2;    // rib thickness along X (mm)
rib_h       = 4;    // rib height above plate (mm), z = 2..6
rib_pitch   = 20;   // centre-to-centre rib spacing (mm)
overlap     = 0.01; // small overlap into plate for a clean union (mm)

union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);

    // Ribs at x = -20, 0, +20, each spanning the full width
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1)/2) * rib_pitch;
        translate([x_c - rib_t/2, -plate_wid/2, plate_t - overlap])
            cube([rib_t, plate_wid, rib_h + overlap]);
    }
}
```

