rib_t       = 2;    // rib thickness along X (mm)
rib_h       = 4;    // rib height above plate (mm), z = 3..7
rib_pitch   = plate_len / (rib_count + 1); // centre-to-centre spacing = 16 mm
overlap     = 0.01; // small overlap so ribs fuse into plate

$fn = 64;

// ---------- Model ----------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);

    // Ribs: centres at -24, -8, 8, 24 (16 mm from plate ends)
