        intersection() {
            translate([0, 0, bowl_cz]) sphere(r = bowl_outer_r);
            translate([-bowl_outer_r - 1, -bowl_outer_r - 1, -1])
                cube([2 * bowl_outer_r + 2, 2 * bowl_outer_r + 2, bowl_cz + 1]);
