// Tapered riser block (square frustum) with top pocket
// Units: mm

base_size    = 80;    // bottom square side (z = 0)
top_size     = 40;    // top square side (z = height)
height       = 20;    // overall height
pocket_size  = 30;    // square pocket side
pocket_depth = 5;     // pocket depth from top face
eps          = 0.5;   // cutter overlap past faces

module frustum() {
    b = base_size / 2;
    t = top_size / 2;
    polyhedron(
        points = [
            [-b, -b, 0], [ b, -b, 0], [ b,  b, 0], [-b,  b, 0],          // bottom 0-3
            [-t, -t, height], [ t, -t, height], [ t,  t, height], [-t,  t, height] // top 4-7
        ],
        faces = [
            [0, 1, 2, 3],   // bottom
            [4, 7, 6, 5],   // top
            [0, 4, 5, 1],   // -Y side
            [1, 5, 6, 2],   // +X side
            [2, 6, 7, 3],   // +Y side
            [3, 7, 4, 0]    // -X side
        ]
    );
}

difference() {
    frustum();
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
