            [ top_size/2, -top_size/2, block_height],
            [ top_size/2,  top_size/2, block_height],
            [-top_size/2,  top_size/2, block_height]
        ],
        faces = [
            [0, 1, 2, 3],  // bottom
            [4, 5, 1, 0],  // front (-Y)
            [5, 6, 2, 1],  // right (+X)
            [6, 7, 3, 2],  // back (+Y)
            [7, 4, 0, 3],  // left (-X)
            [7, 6, 5, 4]   // top
        ]
    );

