// Tapered riser block for raising a beaker
// Solid square frustum with a square pocket in the top face

// ---- Dimensions (mm) ----
base_size    = 100;  // bottom square side length (z = 0)
top_size     = 70;   // top square side length (z = height)
height       = 20;   // overall height of the frustum
pocket_size  = 60;   // square pocket side length
pocket_depth = 8;    // pocket depth from top face
eps          = 0.5;  // overshoot for clean boolean cuts

// ---- Frustum built from polyhedron ----
module frustum(b, t, h) {
    hb = b / 2;
    ht = t / 2;
    polyhedron(
        points = [
            [-hb, -hb, 0], [ hb, -hb, 0], [ hb,  hb, 0], [-hb,  hb, 0], // bottom
            [-ht, -ht, h], [ ht, -ht, h], [ ht,  ht, h], [-ht,  ht, h]  // top
        ],
        faces = [
            [0, 1, 2, 3],  // bottom
            [4, 7, 6, 5],  // top
            [0, 4, 5, 1],  // front (-Y)
            [1, 5, 6, 2],  // right (+X)
            [2, 6, 7, 3],  // back (+Y)
            [3, 7, 4, 0]   // left (-X)
        ]
    );
}

// ---- Part ----
difference() {
    frustum(base_size, top_size, height);

    // Top pocket, extends past the top face
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
