rim_id       = rim_od - 2 * rim_width;   // rim inner diameter
spoke_r0     = hub_d / 2 - 1;            // spoke start radius (overlaps hub)
spoke_r1     = rim_id / 2 + 1;           // spoke end radius (overlaps rim)

difference() {
    union() {
        // Rim ring
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([spoke_r0, -spoke_width / 2, 0])
                    cube([spoke_r1 - spoke_r0, spoke_width, thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
