// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to thickness

// ---- Parameters ----
thickness      = 8;    // overall wheel thickness (Z)
rim_od         = 80;   // rim outer diameter
rim_width      = 6;    // rim radial width
hub_d          = 20;   // hub diameter
axle_d         = 6;    // axle hole diameter
spoke_count    = 5;    // number of spokes
spoke_width    = 5;    // spoke width
spoke_overlap  = 1;    // spoke extension into hub/rim for solid union
eps            = 0.5;  // cutter overshoot past faces

$fn = 128;

// ---- Derived ----
rim_id      = rim_od - 2 * rim_width;          // rim inner diameter
spoke_start = hub_d / 2 - spoke_overlap;       // spoke inner end radius
spoke_end   = rim_id / 2 + spoke_overlap;      // spoke outer end radius
spoke_len   = spoke_end - spoke_start;

// ---- Model ----
difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes (first along +X)
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_start, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
