```openscad
// Spoked wheel for a small sample cart
// Flat part, 6 mm thick, lying on the bed, centred on origin

// ---------------- Parameters ----------------
thickness     = 6;     // overall part thickness (Z)
rim_od        = 100;   // rim outer diameter
rim_width     = 6;     // rim radial width
hub_d         = 14;    // hub outer diameter
axle_d        = 8;     // axle hole diameter
spoke_count   = 6;     // number of spokes
spoke_width   = 5;     // spoke width
eps           = 0.5;   // overcut for clean differences
$fn           = 128;   // resolution for curved shapes

// Derived
rim_r_out = rim_od / 2;              // 50
rim_r_in  = rim_r_out - rim_width;   // 44
hub_r     = hub_d / 2;               // 7

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(h = thickness, r = rim_r_out);
            translate([0, 0, -eps])
                cylinder(h = thickness + 2 * eps, r = rim_r_in);
        }

        // Hub
        cylinder(h = thickness, r = hub_r);

        // Spokes: run from hub centre region into the rim (overlap both)
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([0, -spoke_width / 2, 0])
                    cube([rim_r_in + rim_width / 2, spoke_width, thickness]);
    }

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = axle_d);
}
